fun n (h : n < 5) => by cases n;
  · simp [Nat.zero_lt, Nat.one_lt]; contradiction;
  · simp [Nat.one_lt, Nat.two_lt]; contradiction;
  · simp [Nat.two_lt, Nat.three_lt]; contradiction;
  · simp [Nat.three_lt, Nat.four_lt]; contradiction;
  · simp [Nat.four_lt]; contradiction;

fun n (h : n < 4) => by cases n;
  case uint0 => simp [Nat.zero_mod, Nat.add_zero, Nat.one_mod];
  case uint1 => simp [Nat.one_mod, Nat.add_one];
  case uint2 => simp [Nat.two_mod, Nat.add_two];
  case uint3 => simp [Nat.three_mod, Nat.add_three];
  case uint4 => contradiction h

intros n h. cases n; try { rw Nat.mod_zero, rw Nat.mul_zero, exact Nat.mod_eq_of_le h };
  repeat { rw Nat.mod_eq_of_lt, rw Nat.mul_eq_zero_left, exact Nat.mod_eq_of_le h };
  rw Nat.mod_eq_of_lt, rw Nat.mul_eq_zero_right, exact Nat.mod_eq_of_le h
